import cv2, numpy as np
A=np.load('source_pixels.npz')['rgb']
for i in range(96):
 im=A[i]; hsv=cv2.cvtColor(im,cv2.COLOR_RGB2HSV)
 # orange H roughly 10-30 high sat
 for name,mask in [('o',cv2.inRange(hsv,(8,100,80),(30,255,255))),('p',cv2.inRange(hsv,(120,80,50),(165,255,255)))]:
  mask[:40]=0;mask[90:]=0
  n,lab,st,cent=cv2.connectedComponentsWithStats(mask)
  cs=[]
  for k in range(1,n):
   x,y,w,h,area=st[k]
   if area>=4:cs.append((area,round(cent[k][0],2),round(cent[k][1],2),x,y,w,h))
  cs=sorted(cs,reverse=True)[:3]
  if name=='o': print(f'{i+1:02}',cs,end=' ')
  else: print(cs)
PY"

