import numpy as np
from PIL import Image
A=np.load('source_pixels.npz')['rgb']
for mode in ['median','p20','p80']:
 if mode=='median': B=np.median(A,axis=0)
 elif mode=='p20': B=np.percentile(A,20,axis=0)
 else:B=np.percentile(A,80,axis=0)
 Image.fromarray(B.astype('uint8')).save(mode+'.png')
